var minRefuelStops = function(target, startFuel, stations) {
    const ordered = stations.slice().sort((a, b) => a[0] - b[0]);
    const heap = [];
    const push = (x) => {
        heap.push(x);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] >= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            const n = heap.length;
            while (true) {
                let l = 2 * i + 1, r = 2 * i + 2, big = i;
                if (l < n && heap[l] > heap[big]) big = l;
                if (r < n && heap[r] > heap[big]) big = r;
                if (big === i) break;
                [heap[big], heap[i]] = [heap[i], heap[big]];
                i = big;
            }
        }
        return top;
    };

    let reach = startFuel;
    let idx = 0;
    let stops = 0;

    while (reach < target) {
        while (idx < ordered.length && ordered[idx][0] <= reach) {
            push(ordered[idx][1]);
            idx++;
        }
        if (heap.length === 0) return -1;
        reach += pop();
        stops++;
    }
    return stops;
};
